"""Amostra BAN-08: contas próprias em Decimal; não substitui cobertura integral."""
from pathlib import Path
from decimal import Decimal as D, getcontext
import json, hashlib, datetime
getcontext().prec=40
here=Path(__file__).resolve().parent
root=here.parents[3]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
cat=load(here/'inventario-numerico-197-r1.json');rows={r['id']:r for r in cat['registros']}
source=root/'modulos/e1-termodinamica.html';assert sha(source)=='80eff701a851145bdcf84e27b5f34abe7e7f371ac6bdf803e689dd6c117663d0'
datafile=root/'assets/termodinamica/fun01-dados-v1.json';d=load(datafile); sat=next(x for x in d['agua_saturacao'] if x['p_MPa']==0.2)
Dfrom=lambda x:D(str(x))
p=D('1')*D('0.287')*D('300')/D('0.861');assert p==D('100')
qcal=D('400')/D('4.184');delta=D('1400')-qcal;assert abs(delta-D('1304.4'))<=D('0.05')
water=D('0.900')/D('2.000');x=(water-Dfrom(sat['vf_m3kg']))/(Dfrom(sat['vg_m3kg'])-Dfrom(sat['vf_m3kg']));h=Dfrom(sat['hf_kJkg'])+x*(Dfrom(sat['hg_kJkg'])-Dfrom(sat['hf_kJkg'])); vapor=D('2')*x;gap=D('1798')-(h+D('1'));assert D('0')<=x<=D('1');assert abs(x-D('0.507494454'))<D('0.0000000005');assert abs(h-D('1621.94904'))<D('0.000005');assert gap>0
common={'revisor':'/root/inspect_repo, agente automatizado Corretor','revisao_independente':'PENDENTE','data':'2026-10-29','estado':'AMOSTRA_PRELIMINAR_SEM_APROVACAO'}
def mk(id,**args):return {'id':id,'artigo_sha256':rows[id]['artigo']['sha256'],'fonte_primaria_do_item':{'arquivo':'modulos/e1-termodinamica.html','ancora':'#'+id,'sha256':sha(source)},**common,**args}
items=[
mk('q-e1-01',aplicabilidade='SEM_RESULTADO_NUMERICO_NO_ARTIGO',dados='Fronteira vedada, pistão móvel, calor permitido.',solucao='Massa não cruza; calor e trabalho podem cruzar.',resultado='C; as demais opções atribuem passagem de massa, isolamento ou adiabaticidade necessária.',tolerancia='Não aplicável a um juízo conceitual; nenhuma magnitude a arredondar.',limite='Esse juízo classifica o item, não contabiliza como recálculo de resultado numérico.'),
mk('q-e1-06',aplicabilidade='NUMERICO',dados='m=1 kg, R=0,287 kJ/(kg·K), T=300 K, V=0,861 m³; modelo de gás ideal.',solucao='p=mRT/V; kJ/m³=kPa.',resultado='100 kPa; D. As demais escolhas 0,287, 300, 1 e 86,1 kPa não coincidem com 100.',tolerancia='Igualdade exata para os decimais fornecidos, p=100; não há arredondamento ambíguo.',reproducao={'p_kPa':str(p)},limite='Não se atribui precisão experimental aos dados didáticos.'),
mk('cr-e1-26',aplicabilidade='NUMERICO_COM_HIPOTESE_EDITORIAL',dados='Q sai 400 kJ; agitador fornece 1400 kcal; suplemento: sistema fechado, apenas trocas indicadas, ΔEc/ΔEp desprezíveis e 1 kcal termoquímica=4,184 kJ.',solucao='Q=−400/4,184 kcal; W=−1400 kcal; ΔU=Q−W.',resultado='ΔU≈1304,4 kcal; não supera 5500, logo E sob modelo editorial.',tolerancia='Resolução mostra uma casa decimal: desvio ≤0,05 kcal para 1304,4; margem para o limiar muito maior.',reproducao={'calor_sai_kcal':str(qcal),'deltaU_kcal':str(delta)},limite='Não se infere sistema fechado a partir da figura ou da transcrição oficial isolada.'),
mk('cr-e1-39',aplicabilidade='NUMERICO_ESTUDO_CRITICO_SEM_NOTA',dados='350 cal, 1 cal=4,2 J e 1470 J de trabalho; original é motor cíclico de combustão.',solucao='350×4,2=1470 J. A conclusão de Kelvin–Planck requer calor total de uma única fonte e trabalho líquido do ciclo, sem outros efeitos.',resultado='1470 J exatamente; C é chave documental oficial. No modelo restrito, QH=Wlíq e nenhuma rejeição contrariam Kelvin–Planck.',tolerancia='Igualdade exata conforme conversão estabelecida no enunciado; a condição de modelo não é questão de arredondamento.',limite='Estudo crítico sem pontuação; motor aberto ou outras trocas não são cobertos pela conclusão condicionada.'),
mk('av-e1-31',aplicabilidade='SEM_RESULTADO_NUMERICO_NO_ARTIGO',dados='Comparação PCS/PCI na base comum de combustível e condições de referência.',solucao='Referência da água líquida no PCS e vapor no PCI; diferença é a parcela de condensação quando há água.',resultado='E; A inverte referências, B atribui diferença a calor sensível, C generaliza igualdade, D usa consumo auxiliar.',tolerancia='Não aplicável: alternativas e solução conceituais.',limite='Não se supõe diferença positiva quando não se forma água; plausibilidade dos erros é teórica.'),
mk('fun01-e1-saturacao',aplicabilidade='NUMERICO_ABERTO_AMOSTRA_PARCIAL',dados='m=2 kg, V=0,900 m³, vf=0,00106052 e vg=0,88568 m³/kg, hf=504,70 e hg=2706,2 kJ/kg; medição 1800±2 kJ/kg, previsão ±1 kJ/kg.',solucao='v=V/m; x=(v−vf)/(vg−vf); mv=mx; h=hf+x(hg−hf); separação mínima=1798−(h+1).',resultado='v=0,45 m³/kg; x≈0,507494454; mv≈1,01498891 kg; h≈1621,94904 kJ/kg; afastamento≈175,05096 kJ/kg, intervalos incompatíveis.',tolerancia='Para reprodução dos valores apresentados, metade da última casa exibida. A faixa ±1 kJ/kg é tolerância editorial do enunciado, não incerteza do NIST; rubrica admite 0,1% dos cálculos preservada a decisão.',reproducao={'v_m3kg':str(water),'x':str(x),'m_vapor_kg':str(vapor),'h_kJkg':str(h),'afastamento_kJkg':str(gap)},fonte_dados={'arquivo':'assets/termodinamica/fun01-dados-v1.json','sha256':sha(datafile),'linha':'agua_saturacao p_MPa=0.2; origem declarada NISTIR 5078, sem reconferência da publicação nesta amostra.'},limite='Somente a subparte numérica de saturação/intervalos foi recalcada; outras subpartes, medições alternativas e rubrica completa continuam pendentes.')]
out={'id':'BAN-08','tipo':'AMOSTRA_INICIAL_NAO_EXAUSTIVA','estado':'PREPARACAO_NAO_APROVADA','data':'2026-10-29','metodo':'Contas independentes em Python Decimal (precisão 40), a partir dos dados do artigo e JSON de propriedades. Exemplos não substituem auditoria dos 197 IDs ou revisão independente.','fonte_inventario':{'arquivo':'auditoria/termodinamica/evidencias/BAN-08/inventario-numerico-197-r1.json','sha256':sha(here/'inventario-numerico-197-r1.json')},'casos':items,'limites':['Amostra não encerra BAN-08 e não declara número total de itens numéricos.','As evidências NIST e demais fontes externas são herdadas pelo dado local e devem ser confrontadas no exame de cada caso que delas dependa.','Nenhuma mudança no produto ou controle.']}
(here/'amostra-inicial-r1.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({'amostra':len(items),'fun01_h':str(h),'fun01_afastamento':str(gap),'q26':str(delta),'arquivo_sha256':sha(here/'amostra-inicial-r1.json')},ensure_ascii=False))
